SELECT p.slug project,r.display_name repository,l.root_path,s.path,d.dependency_name,d.requirement,d.dependency_kind,d.target,d.optional FROM repository_dependencies d JOIN source_documents s ON s.id=d.source_document_id JOIN repository_locations l ON l.id=d.repository_location_id JOIN repositories r ON r.id=l.repository_id JOIN projects p ON p.id=r.project_id WHERE l.is_present AND ($2::text IS NULL OR p.slug=$2) AND d.dependency_name ILIKE '%' || $1 || '%' ORDER BY d.dependency_name,r.display_name,l.root_path LIMIT $3
